<script>
const rowsEl=document.getElementById('rows'), activeMath=document.getElementById('activeMath'), activeAnswer=document.getElementById('activeAnswer'), caret=document.getElementById('caret');
let expr='',history=[],redoStack=[],lastAnswer='0',cursor=0;
function pretty(s){
  let safe=s.replace(/</g,'&lt;').replace(/>/g,'&gt;');
  safe=safe.replace(/\^2/g,'<sup>2</sup>').replace(/\^([0-9]+)/g,'<sup>$1</sup>').replace(/\*/g,' × ').replace(/\//g,' ÷ ').replace(/-/g,'−');
  safe=safe.replace(/sqrt\(/g,'√(').replace(/pi/g,'π').replace(/abs\(/g,'|').replace(/\)/g,'|');
  return safe;
}
function calculate(s){
  if(!s.trim())return '';
  try{
    let q=s.replace(/π/g,'Math.PI').replace(/\bans\b/g,lastAnswer).replace(/sqrt\(/g,'Math.sqrt(').replace(/abs\(/g,'Math.abs(').replace(/\^/g,'**').replace(/(\d+(?:\.\d+)?)%/g,'($1/100)');
    if(!/^[0-9+\-*/().,\sA-Za-z]*$/.test(q))return '';
    let val=Function('"use strict";return ('+q+')')();
    if(typeof val!=='number'||!Number.isFinite(val))return '';
    return Number.isInteger(val)?String(val):String(Number(val.toPrecision(10)));
  }catch(e){return ''}
}
function render(){
 activeMath.innerHTML=pretty(expr);
 let result=calculate(expr);
 activeAnswer.textContent=result?'= '+result:'';
 caret.style.display='inline-block';
 rowsEl.innerHTML='';
 history.forEach(item=>{
   let row=document.createElement('div');row.className='expr-row';
   row.innerHTML='<span class="math">'+pretty(item.expr)+'</span><span class="answer">= '+item.answer+'</span>';
   rowsEl.appendChild(row);
 });
}
function insert(v){
 if(v==='sqrt'){expr+='sqrt(';cursor=expr.length}
 else if(v==='root'){expr+='sqrt(';cursor=expr.length}
 else if(v==='abs'){expr+='abs(';cursor=expr.length}
 else if(v==='pi'){expr+='pi';cursor=expr.length}
 else if(v==='ans'){expr+='ans';cursor=expr.length}
 else {expr=expr.slice(0,cursor)+v+expr.slice(cursor);cursor+=v.length}
 render();
}
function submit(){
 const answer=calculate(expr);
 if(!expr.trim()||!answer)return;
 history.push({expr,answer});lastAnswer=answer;redoStack=[];
 expr='';cursor=0;render();
}
function clearAll(){history=[];expr='';cursor=0;lastAnswer='0';redoStack=[];render()}
function undo(){if(expr){redoStack.push(expr);expr='';cursor=0}else if(history.length){let v=history.pop();redoStack.push(v);expr=v.expr;cursor=expr.length}render()}
function redo(){let v=redoStack.pop();if(!v)return;if(typeof v==='string'){expr=v;cursor=expr.length}else history.push(v);render()}
function focusInput(){caret.style.display='inline-block'}
document.querySelectorAll('.key[data-value]').forEach(k=>k.addEventListener('click',()=>insert(k.dataset.value)));
document.querySelectorAll('.key[data-action]').forEach(k=>k.addEventListener('click',()=>{
 const a=k.dataset.action;
 if(a==='enter')submit();
 else if(a==='back'){if(cursor>0){expr=expr.slice(0,cursor-1)+expr.slice(cursor);cursor--}render()}
 else if(a==='left')cursor=Math.max(0,cursor-1);
 else if(a==='right')cursor=Math.min(expr.length,cursor+1);
}));
document.addEventListener('keydown',e=>{
 if(e.key==='Enter'){e.preventDefault();submit()}
 else if(e.key==='Backspace'){e.preventDefault();if(cursor>0){expr=expr.slice(0,cursor-1)+expr.slice(cursor);cursor--}render()}
 else if(e.key==='Escape'){clearAll()}
 else if(/^[0-9.+\-*/(),]$/.test(e.key)){insert(e.key)}
});
render();
</script>
